import { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Activity, Database, Cpu, HardDrive, Network, Users, GitMerge, Lock, X } from 'lucide-react';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';

// Unified Telemetry Data
const SLATE_METRICS = [
  { id: 'cpu', icon: Cpu, label: 'CPU Usage', value: '12.4%', metricClass: 'text-blue-400', details: 'System core execution is running optimally with plenty of headroom for Maestro intents.' },
  { id: 'mem', icon: HardDrive, label: 'Memory (Heap)', value: '842 MB', metricClass: 'text-purple-400', details: 'Heap usage is well within the 4GB allocation. Garbage collection cycle normal.' },
  { id: 'net', icon: Network, label: 'Active Connects', value: '14,204', metricClass: 'text-[hsl(var(--accent))] font-semibold', details: 'Global inbound WebSockets. Traffic is heavy but latency remains low.' },
  { id: 'db', icon: Database, label: 'DB Latency', value: '8ms', metricClass: 'text-emerald-400', details: 'Vector and relation queries responding rapidly at edge nodes.' },
  { id: 'users', icon: Users, label: 'Daily Active', value: '1,248', metricClass: 'text-orange-400', details: 'Peak concurrency achieved. 18% lift from previous cycle.' },
  { id: 'workflows', icon: GitMerge, label: 'Executions', value: '8.4k', metricClass: 'text-blue-500', details: 'Zero-Drift workflow completion rate is at 99.8%.' },
  { id: 'threats', icon: Lock, label: 'Threats Blocked', value: '0', metricClass: 'text-emerald-500 font-bold', details: 'Zero Trust architecture active. No hostile spoofing detected.' },
];

export const OmniSlate = () => {
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Collapse on outside click
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      // If expanding is active and click is outside the Card container, collapse it.
      if (expandedId && containerRef.current && !containerRef.current.contains(event.target as Node)) {
        setExpandedId(null);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [expandedId]);

  return (
    <Card ref={containerRef} className="glass-card hover-lift h-full flex flex-col relative overflow-hidden bg-[#0A0D14]/90 border-[hsl(var(--accent))]/20">
      <div className="custom-drag-handle absolute top-0 right-0 p-3 h-10 w-10 cursor-grab active:cursor-grabbing text-white/20 hover:text-white/60 transition-colors z-20">
        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="9" cy="12" r="1"/><circle cx="9" cy="5" r="1"/><circle cx="9" cy="19" r="1"/><circle cx="15" cy="12" r="1"/><circle cx="15" cy="5" r="1"/><circle cx="15" cy="19" r="1"/></svg>
      </div>

      <CardHeader className="p-4 pb-0 z-10 shrink-0">
        <div className="flex items-center gap-2">
          <Activity className="h-4 w-4 text-[hsl(var(--accent))]" />
          <CardTitle className="text-sm font-semibold text-gray-200 tracking-wide uppercase">OmniSLATE Telemetry</CardTitle>
        </div>
      </CardHeader>

      <CardContent className="p-4 flex-1 flex flex-col justify-end z-10">
        <AnimatePresence mode="popLayout">
          {expandedId && (
            <motion.div
              layoutId={`slate-container-${expandedId}`}
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.95, transition: { duration: 0.2 } }}
              className="absolute inset-0 bg-[#120D1A]/95 backdrop-blur-2xl z-20 p-6 flex flex-col shadow-2xl overflow-y-auto"
            >
              {(() => {
                const metric = SLATE_METRICS.find(m => m.id === expandedId);
                if (!metric) return null;
                const Icon = metric.icon;
                return (
                  <div className="h-full flex flex-col">
                    <div className="flex justify-between items-start">
                      <div className="flex items-center gap-4">
                        <motion.div layoutId={`slate-icon-${metric.id}`} className="h-14 w-14 rounded-2xl bg-white/5 border border-white/10 flex items-center justify-center shadow-lg">
                          <Icon className={`h-7 w-7 ${metric.metricClass}`} />
                        </motion.div>
                        <div>
                          <h3 className="text-xl font-bold text-white tracking-tight">{metric.label}</h3>
                          <p className={`text-2xl font-mono mt-1 ${metric.metricClass}`}>{metric.value}</p>
                        </div>
                      </div>
                      <button onClick={(e) => { e.stopPropagation(); setExpandedId(null); }} className="p-2 hover:bg-white/10 hover:text-white rounded-full transition-colors text-gray-400 focus:outline-none focus:ring-2 focus:ring-accent">
                        <X className="h-5 w-5" />
                      </button>
                    </div>
                    
                    <div className="mt-8 flex-1 flex flex-col">
                       <p className="text-gray-300 text-sm leading-relaxed max-w-lg">{metric.details}</p>
                       
                       {/* Mock Data Visualization Area */}
                       <div className="mt-auto h-32 w-full rounded-xl bg-white/5 border border-white/10 flex items-end p-4 gap-2 shadow-inner">
                           {[40, 70, 45, 90, 65, 80, 55, 100].map((h, i) => (
                             <motion.div 
                               // eslint-disable-next-line react/no-array-index-key
                               key={i}
                               initial={{ height: 0 }}
                               animate={{ height: `${h}%` }}
                               transition={{ delay: i * 0.05, type: 'spring' }}
                               className="flex-1 bg-gradient-to-t from-[hsl(var(--accent))]/20 to-[hsl(var(--accent))]/80 rounded-sm"
                             />
                           ))}
                       </div>
                    </div>
                  </div>
                );
              })()}
            </motion.div>
          )}
        </AnimatePresence>

        {/* Minimal Idle Row */}
        <div className="flex flex-wrap items-center gap-2 mt-auto relative z-10 w-full justify-between sm:justify-start">
          <TooltipProvider delayDuration={0}>
            {SLATE_METRICS.map((metric) => {
              const Icon = metric.icon;
              const isSelected = expandedId === metric.id;
              return (
                <Tooltip key={metric.id}>
                  <TooltipTrigger asChild>
                    <motion.button
                      layoutId={isSelected ? undefined : `slate-icon-${metric.id}`}
                      onClick={(e) => { e.stopPropagation(); setExpandedId(metric.id); }}
                      onPanEnd={(_, info) => {
                        // Swipe up detection
                        if (info.offset.y < -30) {
                          setExpandedId(metric.id);
                        }
                      }}
                      className={`group relative h-10 w-10 sm:h-12 sm:w-12 rounded-xl flex items-center justify-center transition-all duration-300 cursor-pointer outline-none focus:ring-2 focus:ring-accent ${isSelected ? 'opacity-0 scale-50' : 'bg-white/5 hover:bg-white/15 border border-white/5 opacity-100 scale-100 shadow-sm'}`}
                      data-testid={`telemetry-${metric.id}`}
                      aria-label={`View details for ${metric.label}`}
                    >
                      <Icon className={`h-5 w-5 sm:h-6 sm:w-6 transition-all duration-300 ${isSelected ? metric.metricClass : 'text-gray-400 group-hover:text-white group-hover:scale-110'}`} />
                      <span className="sr-only">{metric.label}</span>
                    </motion.button>
                  </TooltipTrigger>
                  {!expandedId && (
                    <TooltipContent side="top" className="flex items-center gap-2 px-3 py-2 bg-[#120D1A]/95 border-[hsl(var(--accent))]/50 backdrop-blur-md z-50 shadow-2xl" data-testid={`telemetry-tooltip-${metric.id}`}>
                      <span className="text-gray-400 text-xs font-semibold uppercase tracking-wider">{metric.label}</span>
                      <span className={`font-mono text-sm ${metric.metricClass}`}>
                        {metric.value}
                      </span>
                    </TooltipContent>
                  )}
                </Tooltip>
              );
            })}
          </TooltipProvider>
        </div>
      </CardContent>
    </Card>
  );
};

/**
 * DATABASE ABSTRACTION LAYER - INTEGRATION TESTS
 *
 * Tests against real Supabase instance (or test database)
 * Run with: npm run test:integration
 */

import { describe, it, expect, beforeAll, afterAll, beforeEach } from 'vitest'
import { createDatabase } from '../../src/lib/database'
import type { IDatabase } from '../../src/lib/database'
import { getIntegrationConfig } from './setup-helpers'

// ============================================================================
// SETUP
// ============================================================================

const { supabaseUrl, supabaseKey, requireIntegration, hasCreds, suite } = getIntegrationConfig()

let db: IDatabase
let testUserId: string

// ============================================================================
// INTEGRATION TESTS
// ============================================================================

describe('Database Integration Tests', () => {
  if (!hasCreds && requireIntegration) {
    it('requires Supabase test credentials', () => {
      throw new Error(
        'Test Supabase credentials not configured. Set VITE_SUPABASE_URL and VITE_SUPABASE_ANON_KEY (or VITE_SUPABASE_PUBLISHABLE_KEY).'
      )
    })
    return
  }

  beforeAll(async () => {
    if (!hasCreds && requireIntegration) return;

    db = createDatabase({
      provider: 'supabase',
      url: supabaseUrl,
      apiKey: supabaseKey,
      serviceRoleKey: supabaseKey,
      debug: true,
    })

    // Verify connection
    const isHealthy = await db.ping()
    if (!isHealthy) {
      throw new Error('Database connection failed')
    }

    console.log('Γ£à Connected to test database')
  })

  afterAll(async () => {
    if (!hasCreds && requireIntegration) return;
    // Cleanup: Delete test user if created
    if (testUserId) {
      await db.deleteById('users', testUserId)
    }
  })
  // -------------------------------------------------------------------------
  // HEALTH CHECK
  // -------------------------------------------------------------------------

  describe('Health Check', () => {
    it('should ping database successfully', async () => {
      const isHealthy = await db.ping()
      expect(isHealthy).toBe(true)
    })
  })

  // -------------------------------------------------------------------------
  // QUERY OPERATIONS
  // -------------------------------------------------------------------------

  describe('Query Operations', () => {
    beforeEach(async () => {
      // Create test user
      const { data: user } = await db.insert('users', {
        email: `test-${Date.now()}@example.com`,
        name: 'Test User',
      })

      if (user && 'id' in user) {
        testUserId = user.id as string
      }
    })

    it('should find user by ID', async () => {
      const { data: user, error } = await db.findById('users', testUserId)

      expect(error).toBeNull()
      expect(user).not.toBeNull()
      expect(user).toHaveProperty('id', testUserId)
      expect(user).toHaveProperty('email')
    })

    it('should find users with filters', async () => {
      const { data: users, error } = await db.find('users', {
        filters: [
          { column: 'id', operator: '=', value: testUserId },
        ],
      })

      expect(error).toBeNull()
      expect(users).toHaveLength(1)
      expect(users?.[0]).toHaveProperty('id', testUserId)
    })

    it('should count users', async () => {
      const { data: count, error } = await db.count('users')

      expect(error).toBeNull()
      expect(count).toBeGreaterThan(0)
    })
  })

  // -------------------------------------------------------------------------
  // MUTATION OPERATIONS
  // -------------------------------------------------------------------------

  describe('Mutation Operations', () => {
    it('should insert a new user', async () => {
      const email = `test-insert-${Date.now()}@example.com`

      const { data: user, error } = await db.insert('users', {
        email,
        name: 'Insert Test User',
      })

      expect(error).toBeNull()
      expect(user).not.toBeNull()
      expect(user).toHaveProperty('id')
      expect(user).toHaveProperty('email', email)

      // Cleanup
      if (user && 'id' in user) {
        await db.deleteById('users', user.id as string)
      }
    })

    it('should update user by ID', async () => {
      // Create test user
      const { data: user } = await db.insert('users', {
        email: `test-update-${Date.now()}@example.com`,
        name: 'Update Test User',
      })

      expect(user).not.toBeNull()
      const userId = (user as any).id

      // Update user
      const { data: updated, error } = await db.updateById('users', userId, {
        name: 'Updated Name',
      })

      expect(error).toBeNull()
      expect(updated).toHaveProperty('name', 'Updated Name')

      // Cleanup
      await db.deleteById('users', userId)
    })

    it('should delete user by ID', async () => {
      // Create test user
      const { data: user } = await db.insert('users', {
        email: `test-delete-${Date.now()}@example.com`,
        name: 'Delete Test User',
      })

      expect(user).not.toBeNull()
      const userId = (user as any).id

      // Delete user
      const { data: success, error } = await db.deleteById('users', userId)

      expect(error).toBeNull()
      expect(success).toBe(true)

      // Verify deletion
      const { data: deletedUser } = await db.findById('users', userId)
      expect(deletedUser).toBeNull()
    })
  })

  // -------------------------------------------------------------------------
  // PAGINATION
  // -------------------------------------------------------------------------

  describe('Pagination', () => {
    beforeAll(async () => {
      // Create 5 test users
      for (let i = 0; i < 5; i++) {
        await db.insert('users', {
          email: `test-pagination-${i}-${Date.now()}@example.com`,
          name: `Pagination User ${i}`,
        })
      }
    })

    it('should paginate results with limit', async () => {
      const { data: users, error } = await db.find('users', {
        limit: 3,
      })

      expect(error).toBeNull()
      expect(users).toHaveLength(3)
    })

    it('should paginate results with offset', async () => {
      const { data: page1 } = await db.find('users', { limit: 2, offset: 0 })
      const { data: page2 } = await db.find('users', { limit: 2, offset: 2 })

      expect(page1).toHaveLength(2)
      expect(page2).toHaveLength(2)

      // Pages should have different users
      const page1Ids = page1?.map((u: any) => u.id) || []
      const page2Ids = page2?.map((u: any) => u.id) || []

      expect(page1Ids).not.toEqual(page2Ids)
    })
  })

  // -------------------------------------------------------------------------
  // TRANSACTIONS
  // -------------------------------------------------------------------------

  describe('Transactions', () => {
    it('should execute operations in transaction', async () => {
      const email1 = `test-tx-1-${Date.now()}@example.com`
      const email2 = `test-tx-2-${Date.now()}@example.com`

      const { data: result, error } = await db.transaction(async (tx: any) => {
        await tx.insert('users', { email: email1, name: 'TX User 1' })
        await tx.insert('users', { email: email2, name: 'TX User 2' })
        return { success: true }
      })

      expect(error).toBeNull()
      expect(result).toEqual({ success: true })

      // Verify both users were inserted
      const { data: user1 } = await db.findOne('users', {
        filters: [{ column: 'email', operator: '=', value: email1 }],
      })
      const { data: user2 } = await db.findOne('users', {
        filters: [{ column: 'email', operator: '=', value: email2 }],
      })

      expect(user1).not.toBeNull()
      expect(user2).not.toBeNull()

      // Cleanup
      if (user1 && (user1 as any).id) await db.deleteById('users', (user1 as any).id)
      if (user2 && (user2 as any).id) await db.deleteById('users', (user2 as any).id)
    })
  })


  // ERROR HANDLING
  // -------------------------------------------------------------------------

  describe('Error Handling', () => {
    it('should handle non-existent record gracefully', async () => {
      const { data: user, error } = await db.findById('users', 'non-existent-id')

      expect(error).toBeNull()
      expect(user).toBeNull()
    })

    it('should handle invalid table name', async () => {
      const { data: users, error } = await db.find('non_existent_table')

      expect(error).not.toBeNull()
      expect(users).toBeNull()
    })

    it('should require filters for delete operation', async () => {
      const { data: success, error } = await db.delete('users')

      expect(error).not.toBeNull()
      expect(error?.message).toContain('filter')
      expect(success).toBeNull()
    })
  })
})

/**
 * STORAGE ABSTRACTION LAYER - INTEGRATION TESTS
 *
 * Tests against real Supabase Storage instance
 * Run with: npm run test:integration
 */

import { describe, it, expect, beforeAll, afterAll } from 'vitest'
import { createStorage } from '../../src/lib/storage'
import type { IStorage } from '../../src/lib/storage'
import { getIntegrationConfig } from './setup-helpers'

// ============================================================================
// SETUP
// ============================================================================

const { supabaseUrl, supabaseKey, requireIntegration, hasCreds, suite } = getIntegrationConfig()

let storage: IStorage
const testBucket = 'test-integration'
const testFiles: string[] = []

// Helper: Register file for cleanup
function registerTestFile(path: string) {
  testFiles.push(path)
}

// ============================================================================
// INTEGRATION TESTS
// ============================================================================

describe('Storage Integration Tests', () => {
  if (!hasCreds && requireIntegration) {
    it('requires Supabase test credentials', () => {
      throw new Error(
        'Test Supabase credentials not configured. Set VITE_SUPABASE_URL and VITE_SUPABASE_ANON_KEY (or VITE_SUPABASE_PUBLISHABLE_KEY).'
      )
    })
    return
  }

  beforeAll(async () => {
    if (!hasCreds && requireIntegration) return;

    storage = createStorage({
      provider: 'supabase',
      url: supabaseUrl,
      apiKey: supabaseKey,
      serviceRoleKey: supabaseKey,
      debug: true,
    })

    // Verify connection
    const isHealthy = await storage.ping()
    if (!isHealthy) {
      throw new Error('Storage connection failed')
    }

    // Create test bucket
    const { error } = await storage.createBucket(testBucket, { public: true })
    if (error && !error.message.includes('already exists')) {
      console.warn('Could not create test bucket:', error.message)
    }

    console.log('Γ£à Connected to test storage')
  })

  afterAll(async () => {
    if (!hasCreds && requireIntegration) return;

    // Cleanup: Delete all test files
    if (testFiles.length > 0) {
      await storage.deleteMany(testBucket, testFiles)
    }

    console.log('≡ƒº╣ Cleaned up test files')
  })
  // -------------------------------------------------------------------------
  // HEALTH CHECK
  // -------------------------------------------------------------------------

  describe('Health Check', () => {
    it('should ping storage successfully', async () => {
      const isHealthy = await storage.ping()
      expect(isHealthy).toBe(true)
    })
  })

  // -------------------------------------------------------------------------
  // BUCKET OPERATIONS
  // -------------------------------------------------------------------------

  describe('Bucket Operations', () => {
    it('should list buckets', async () => {
      const { data: buckets, error } = await storage.listBuckets()

      expect(error).toBeNull()
      expect(buckets).toBeInstanceOf(Array)
      expect(buckets).toContain(testBucket)
    })

    it('should create a new bucket', async () => {
      const bucketName = `test-create-${Date.now()}`

      const { data: success, error } = await storage.createBucket(bucketName, {
        public: false,
      })

      expect(error).toBeNull()
      expect(success).toBe(true)

      // Verify bucket exists
      const { data: buckets } = await storage.listBuckets()
      expect(buckets).toContain(bucketName)

      // Cleanup
      await storage.deleteBucket(bucketName)
    })

    it('should delete empty bucket', async () => {
      const bucketName = `test-delete-${Date.now()}`

      // Create bucket
      await storage.createBucket(bucketName)

      // Delete bucket
      const { data: success, error } = await storage.deleteBucket(bucketName)

      expect(error).toBeNull()
      expect(success).toBe(true)

      // Verify bucket is gone
      const { data: buckets } = await storage.listBuckets()
      expect(buckets).not.toContain(bucketName)
    })
  })

  // -------------------------------------------------------------------------
  // FILE OPERATIONS
  // -------------------------------------------------------------------------

  describe('File Upload & Download', () => {
    const testPath = `integration-test-${Date.now()}.txt`

    it('should upload a file', async () => {
      const content = 'Hello from integration test!'
      const blob = new Blob([content], { type: 'text/plain' })

      const { data: url, error } = await storage.upload(
        testBucket,
        testPath,
        blob,
        {
          contentType: 'text/plain',
          cacheControl: '3600',
        }
      )

      expect(error).toBeNull()
      expect(url).toContain(testBucket)
      expect(url).toContain(testPath)

      registerTestFile(testPath)
    })

    it('should check if file exists', async () => {
      const { data: exists, error } = await storage.exists(testBucket, testPath)

      expect(error).toBeNull()
      expect(exists).toBe(true)
    })

    it('should get file metadata', async () => {
      const { data: file, error } = await storage.getMetadata(testBucket, testPath)

      expect(error).toBeNull()
      expect(file).not.toBeNull()
      expect(file).toHaveProperty('name')
      expect(file).toHaveProperty('size')
      expect(file).toHaveProperty('contentType', 'text/plain')
    })

    it('should download a file', async () => {
      const { data: blob, error } = await storage.download(testBucket, testPath)

      expect(error).toBeNull()
      expect(blob).toBeInstanceOf(Blob)

      const text = await blob?.text()
      expect(text).toContain('Hello from integration test!')
    })

    it('should get public URL', () => {
      const url = storage.getPublicUrl(testBucket, testPath)

      expect(url).toContain(testBucket)
      expect(url).toContain(testPath)
      expect(url).toMatch(/^https?:\/\//)
    })

    it('should create signed URL', async () => {
      const { data: signedUrl, error } = await storage.createSignedUrl(
        testBucket,
        testPath,
        { expiresIn: 3600 }
      )

      expect(error).toBeNull()
      expect(signedUrl).toMatch(/^https?:\/\//)

      // Signed URL should be accessible
      const response = await fetch(signedUrl!)
      expect(response.ok).toBe(true)

      const text = await response.text()
      expect(text).toContain('Hello from integration test!')
    })

    it('should delete a file', async () => {
      const { data: success, error } = await storage.delete(testBucket, testPath)

      expect(error).toBeNull()
      expect(success).toBe(true)

      // Verify file is gone
      const { data: exists } = await storage.exists(testBucket, testPath)
      expect(exists).toBe(false)

      // Remove from cleanup list
      const index = testFiles.indexOf(testPath)
      if (index > -1) testFiles.splice(index, 1)
    })
  })

  // -------------------------------------------------------------------------
  // BATCH OPERATIONS
  // -------------------------------------------------------------------------

  describe('Batch Operations', () => {
    it('should delete multiple files', async () => {
      // Upload 3 test files
      const paths = [
        `batch-test-1-${Date.now()}.txt`,
        `batch-test-2-${Date.now()}.txt`,
        `batch-test-3-${Date.now()}.txt`,
      ]

      for (const path of paths) {
        await storage.upload(
          testBucket,
          path,
          new Blob(['test'], { type: 'text/plain' })
        )
        registerTestFile(path)
      }

      // Delete all 3 files
      const { data: success, error } = await storage.deleteMany(testBucket, paths)

      expect(error).toBeNull()
      expect(success).toBe(true)

      // Verify all files are gone
      for (const path of paths) {
        const { data: exists } = await storage.exists(testBucket, path)
        expect(exists).toBe(false)

        // Remove from cleanup list
        const index = testFiles.indexOf(path)
        if (index > -1) testFiles.splice(index, 1)
      }
    })

    it('should create signed URLs for multiple files', async () => {
      // Upload 2 test files
      const paths = [
        `batch-signed-1-${Date.now()}.txt`,
        `batch-signed-2-${Date.now()}.txt`,
      ]

      for (const path of paths) {
        await storage.upload(
          testBucket,
          path,
          new Blob(['test'], { type: 'text/plain' })
        )
        registerTestFile(path)
      }

      // Create signed URLs
      const { data: urls, error } = await storage.createSignedUrls(
        testBucket,
        paths,
        { expiresIn: 3600 }
      )

      expect(error).toBeNull()
      expect(urls).toHaveLength(2)
      expect(urls?.every(url => url.match(/^https?:\/\//))).toBe(true)
    })
  })

  // -------------------------------------------------------------------------
  // FILE LISTING
  // -------------------------------------------------------------------------

  describe('File Listing', () => {
    beforeAll(async () => {
      // Create test files with prefix
      const prefix = `list-test-${Date.now()}`
      for (let i = 0; i < 5; i++) {
        const path = `${prefix}/file-${i}.txt`
        await storage.upload(
          testBucket,
          path,
          new Blob([`Content ${i}`], { type: 'text/plain' })
        )
        registerTestFile(path)
      }
    })

    it('should list all files in bucket', async () => {
